    if (!fs.existsSync(adminP)) fs.writeFileSync(adminP, HTML_ADMIN, 'utf8');

    const custP = path.join(PUBLIC_DIR, 'customer.html');
    if (!fs.existsSync(custP)) fs.writeFileSync(custP, HTML_CUSTOMER, 'utf8');

    const zP = path.join(ASSETS_DIR, 'zen-money.svg');
    if (!fs.existsSync(zP)) fs.writeFileSync(zP, SVG_ZEN, 'utf8');

    const kP = path.join(ASSETS_DIR, 'karta-loan.svg');
    if (!fs.existsSync(kP)) fs.writeFileSync(kP, SVG_KARTA, 'utf8');

