    if (!fs.existsSync(ptmP)) fs.writeFileSync(ptmP, SVG_PAYTM, 'utf8');

    const phpP = path.join(ASSETS_DIR, 'phonepe.svg');
    if (!fs.existsSync(phpP)) fs.writeFileSync(phpP, SVG_PHONEPE, 'utf8');

    const logos = readJSON(LOGOS_FILE, []);
