app.get('/api/customers/:token', (req, res) => {
  const { token } = req.params;
  const expiredTokens = readJSON(EXPIRED_TOKENS_FILE, []);
  if (expiredTokens.includes(token)) {
    return res.json({ expired: true, message: 'This payment link has expired.' });
  }

  const customers = readJSON(CUSTOMERS_FILE, []);
  let customer = customers.find(c => c.token === token || c.id === token);

  if (!customer) {
    return res.json({ expired: true, message: 'This payment link has expired.' });
  }

  if (customer.isExpired || customer.status === 'Expired') {
    return res.json({ expired: true, message: 'This payment link has expired.' });
  }

  const renewAmount = Math.round(customer.repaymentAmount * 0.4);

  return res.json({
    customer: {
      ...customer,
      calculatedRenewAmount: renewAmount
    }
  });
});

app.delete('/api/customers/:id', checkAuth, (req, res) => {
  const { id } = req.params;
  let customers = readJSON(CUSTOMERS_FILE, []);
  const custToDelete = customers.find(c => c.id === id || c.token === id);

  if (custToDelete) {
    const expiredTokens = readJSON(EXPIRED_TOKENS_FILE, []);
    if (!expiredTokens.includes(custToDelete.token)) {
      expiredTokens.push(custToDelete.token);
    }
    if (!expiredTokens.includes(custToDelete.id)) {
      expiredTokens.push(custToDelete.id);
    }
    writeJSON(EXPIRED_TOKENS_FILE, expiredTokens);
  }

  customers = customers.filter(c => c.id !== id && c.token !== id);
  writeJSON(CUSTOMERS_FILE, customers);
  return res.json({ success: true, message: 'Customer link expired and deleted' });
});

app.post('/api/customers/:token/submit-utr', (req, res) => {
  const { token } = req.params;
  const { utr } = req.body;

  if (!utr || !/^\d{12}$/.test(utr.trim())) {
    return res.status(400).json({ error: 'Please enter a valid 12-digit numeric UTR' });
  }

  const customers = readJSON(CUSTOMERS_FILE, []);
  let index = customers.findIndex(c => c.token === token || c.id === token);

  if (index === -1) {
    // If demo token, create the customer entry so it persists across checking
    const newCust = {
      id: 'cust_' + Date.now(),
      token: token,
      appName: 'Zen Money',
      appLogo: '/assets/zen-money.svg',
      customerName: 'BHAVIK KAMLESH SANGHVI',
      repaymentAmount: 12540,
      loanAmount: 11000,
      receivedAmount: 11000,
      bankAddress: 'HDFC BANK, ANDHERI (W), MUMBAI - 746388853(ifsc:UHDK84738)',
      amountPaid: 0,
      overdueDays: 2,
      lateFee: 1540,
      amountReceivedDate: '23-10-2026',
      dueDate: '30-10-2026',
      renewalDays: 7,
      renewalFee: 4400,
      upiId: 'Q609224859@ybl',
      merchantName: 'Zen Money Pay',
      status: 'Checking',
      submittedUtr: utr.trim(),
      utrSubmittedAt: new Date().toISOString(),
      createdAt: new Date().toISOString()
    };
    customers.unshift(newCust);
    writeJSON(CUSTOMERS_FILE, customers);
    return res.json({
      success: true,
      message: 'UTR submitted successfully! Verification in progress.',
      utr: utr.trim(),
      status: 'Checking'
    });
  }

  customers[index].submittedUtr = utr.trim();
  customers[index].utrSubmittedAt = new Date().toISOString();
  customers[index].status = 'Checking';

  writeJSON(CUSTOMERS_FILE, customers);
  return res.json({
    success: true,
    message: 'UTR submitted successfully! Verification in progress.',
    utr: utr.trim(),
    status: 'Checking'
  });
});

// Update customer verification status (Admin only)
app.all(['/api/customers/:id/status', '/api/customers/:id/update-status'], checkAuth, (req, res) => {
  if (req.method !== 'POST' && req.method !== 'PATCH' && req.method !== 'PUT') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { id } = req.params;
  const { status, note } = req.body;

  if (!status) {
    return res.status(400).json({ error: 'Status is required' });
  }

  const customers = readJSON(CUSTOMERS_FILE, []);
  const index = customers.findIndex(c => c.id === id || c.token === id);

  if (index === -1) {
    return res.status(404).json({ error: 'Customer not found' });
  }

  customers[index].status = status;
  if (note !== undefined) {
    customers[index].statusNote = note;
  }
  customers[index].statusUpdatedAt = new Date().toISOString();

  writeJSON(CUSTOMERS_FILE, customers);
  return res.json({
    success: true,
    message: `Status updated to ${status}`,
    customer: customers[index]
  });
});

app.get('/api/qrcode', async (req, res) => {
  try {
    const { upi, amount, name } = req.query;
    if (!upi) return res.status(400).send('UPI ID is required');

    const upiUri = 'upi://pay?pa=' + encodeURIComponent(upi) + '&pn=' + encodeURIComponent(name || 'Merchant') + '&am=' + encodeURIComponent(amount || '') + '&cu=INR&tn=Payment';

    const qrDataUrl = await QRCode.toDataURL(upiUri, {
      errorCorrectionLevel: 'H',
      margin: 1,
      width: 280,
      color: { dark: '#000000', light: '#ffffff' }
    });

    res.json({ qrDataUrl, upiUri });
  } catch (err) {
    res.status(500).json({ error: 'Failed to generate QR code' });
  }
});

