// Helper to serve HTML with strict no-cache headers
function sendFreshHtml(res, filePath, fallbackHtml) {
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
  if (fs.existsSync(filePath)) {
    return res.type('html').send(fs.readFileSync(filePath, 'utf8'));
  }
  return res.type('html').send(fallbackHtml);
}

app.get('/login', (req, res) => {
  return sendFreshHtml(res, path.join(PUBLIC_DIR, 'admin-login.html'), HTML_LOGIN);
});

